3733	static int book_utf8_trim(char *buf, int len)
3734	{
3735	    if (len <= 0) return 0;
3736	    int n = len;
3737	    while (n > 0) {
3738	        unsigned char c = (unsigned char)buf[n - 1];
3739	        if ((c & 0x80) == 0) break;
3740	        if ((c & 0xC0) == 0xC0) break;
3741	        n--;
3742	    }
3743	    buf[n] = '\0';
3744	    return n;
3745	}
